    q16924: { h: "3746204d09e5", text: "Offshore wind means climbing from the boat on a swinging ladder: would you like the swinging ladder?" },
    q16925: { h: "9ef8cf99b57a", text: "A tidal site means careful steps on slippery rocks: would you enjoy the steps on slippery rock?" },
    q16926: { h: "e03250c05807", text: "Desalination means hard work in gloves changing membranes: would you like changing membranes?" },
    q16927: { h: "fe9b9bc52a49", text: "Sea cleaning means picking, bent over, with a sack on the shore: would you enjoy picking on the shore?" },
    q16928: { h: "f1433e11d814", text: "Marine insurance means rounds of the docks for survey reports: would you like the survey rounds?" },
    q16929: { h: "0893d55a64fe", text: "Planting mangroves means hard work on your knees with saplings in the mud: would you enjoy the saplings in the mud?" },
    q17859: { h: "60f2d00a4a74", text: "A climate tech customer waits for a subsidy announcement: could you put up with the wait for the subsidy?" },
    q17860: { h: "f6560fdf0d06", text: "An ESG report is made by dragging data out of the departments: could you bear the dragging out?" },
    q17861: { h: "6a19d095546c", text: "The carbon market price swings with policy news: could you put up with the policy swing?" },
    q17862: { h: "306b19773cae", text: "A customer keeps putting off a climate risk warning: could you bear the warning being put off?" },
    q17863: { h: "1918a1297ae2", text: "A biodiversity count has to be repeated season after season: could you put up with the seasons of counting?" },
    q17864: { h: "6e0ba27c45a3", text: "Approval of a green loan is slow in layers of paper: could you bear the layers of the loan?" },
    q17865: { h: "fae015084340", text: "The supply chain takes months to adopt a trace system: could you put up with the months of the chain?" },
    q17866: { h: "3c0bb10b19c7", text: "A climate insurance claim waits for the rainfall data to be confirmed: could you bear the wait for confirmation?" },
    q17867: { h: "88d1af7f39fc", text: "The path to net-zero is a journey in instalments over decades: will you walk the journey of instalments?" },
    q17868: { h: "ab666469ef6a", text: "A climate service customer moves slowly away from the expectation of free service: could you put up with the expectation of free service?" },
    q17869: { h: "5ebbd1624fc9", text: "A seaweed crop is broken again and again by waves and weather: could you bear the breaking by waves?" },
    q17870: { h: "1b7bfb00eabd", text: "Blue biotech takes years from sample to product: would you count the years of a sample?" },
    q17871: { h: "eb073ec3493a", text: "Buoy repair in ocean monitoring waits for the weather: could you bear the wait for the buoy?" },
    q17872: { h: "4c3b521797b2", text: "In deep-sea exploration one dive demands months of preparation: could you put up with the preparation for a dive?" },
    q17873: { h: "dab0efdb5814", text: "Marine energy learns by losing to salt and rust again and again: could you bear the losses to rust?" },
    q17874: { h: "ff22b486ae03", text: "Approval for offshore wind takes years in layers of marine rules: would you count the years at sea?" },
    q17875: { h: "ae7c6055d49e", text: "Investors for a tidal project gather slowly: could you put up with the slowness of investors?" },
    q17876: { h: "b1c7e5c19450", text: "The cycle of changing desalination membranes keeps you counting the cost: could you bear the membrane cycle?" },
    q17877: { h: "bcd5b0cca3c6", text: "The pile in sea cleaning seems endless: could you put up with the endless pile?" },
    q17878: { h: "cb9dc887f9ea", text: "A marine insurance claim stops for months on the survey report: could you bear the hold for the survey?" },
    q17879: { h: "5dcf5192778d", text: "The recognition framework for blue carbon is still being built slowly: could you put up with the slowness of the framework?" },
